import math
import pytest
from hypothesis import given
import hypothesis.strategies as st

from solution import prime_fib


# ---- obviously-correct reference model (independent of solution.py) ----

def ref_is_prime(num: int) -> bool:
    if not isinstance(num, int) or isinstance(num, bool):
        return False
    if num < 2:
        return False
    if num % 2 == 0:
        return num == 2
    r = math.isqrt(num)
    d = 3
    while d <= r:
        if num % d == 0:
            return False
        d += 2
    return True


def ref_fibs_up_to(limit: int):
    fibs = []
    a, b = 0, 1
    while a <= limit:
        fibs.append(a)
        a, b = b, a + b
    return fibs


def ref_prime_fib(n: int) -> int:
    assert isinstance(n, int) and not isinstance(n, bool) and n >= 1
    found = []
    a, b = 0, 1
    # generate fibs 0,1,1,2,3,5,... and collect primes
    while len(found) < n:
        if ref_is_prime(a):
            found.append(a)
        a, b = b, a + b
    return found[-1]


def ref_all_prime_fibs_up_to(limit: int):
    return [f for f in ref_fibs_up_to(limit) if ref_is_prime(f)]


# ---- explicit spec examples ----

@pytest.mark.parametrize("n, expected", [
    (1, 2),
    (2, 3),
    (3, 5),
    (4, 13),
    (5, 89),
])
def test_spec_examples(n, expected):
    assert prime_fib(n) == expected


# extended values derived from spec definition (fib + prime), cross-checked
# sequence of fibonacci primes begins 2,3,5,13,89,233,1597,28657,514229
@pytest.mark.parametrize("n, expected", [
    (6, 233),
    (7, 1597),
    (8, 28657),
])
def test_extended_prime_fibs(n, expected):
    assert prime_fib(n) == expected


# ---- property tests ----

@given(st.integers(min_value=1, max_value=7))
def test_result_is_prime(n):
    assert ref_is_prime(prime_fib(n))


@given(st.integers(min_value=1, max_value=7))
def test_result_is_integer_and_prime_type(n):
    r = prime_fib(n)
    assert isinstance(r, int) and not isinstance(r, bool)
    assert r >= 2


@given(st.integers(min_value=1, max_value=8))
def test_result_is_fibonacci_number(n):
    r = prime_fib(n)
    assert r in set(ref_fibs_up_to(r))


@given(st.integers(min_value=1, max_value=7))
def test_equivalence_to_reference_model(n):
    assert prime_fib(n) == ref_prime_fib(n)


@given(st.integers(min_value=1, max_value=6), st.integers(min_value=1, max_value=6))
def test_strictly_increasing_with_n(a, b):
    if a < b:
        assert prime_fib(a) < prime_fib(b)
    elif a > b:
        assert prime_fib(a) > prime_fib(b)
    else:
        assert prime_fib(a) == prime_fib(b)


@given(st.integers(min_value=1, max_value=7))
def test_exactly_n_prime_fibs_at_or_below_result(n):
    r = prime_fib(n)
    below_or_equal = ref_all_prime_fibs_up_to(r)
    assert len(below_or_equal) == n
    assert below_or_equal[-1] == r


@given(st.integers(min_value=1, max_value=7))
def test_minimality_no_smaller_missing(n):
    r = prime_fib(n)
    # every prime fib below r must be one of the first n-1
    smaller = [x for x in ref_all_prime_fibs_up_to(r - 1)]
    assert len(smaller) == n - 1
    # r must be the smallest prime-fib strictly greater than any smaller one
    if smaller:
        assert r > max(smaller)


@given(st.integers(min_value=1, max_value=6))
def test_successor_relation(n):
    # consecutive values must be consecutive in the prime-fib sequence:
    # no prime fib strictly between them
    a = prime_fib(n)
    b = prime_fib(n + 1)
    assert a < b
    between = [x for x in ref_all_prime_fibs_up_to(b - 1) if x > a]
    assert between == []


@given(st.integers(min_value=1, max_value=6))
def test_idempotence_same_n_same_result(n):
    assert prime_fib(n) == prime_fib(n)


def test_first_prime_fib_is_smallest_prime_fib():
    # 2 is the smallest prime that is also a fibonacci number
    assert prime_fib(1) == 2
    assert prime_fib(1) == min(ref_all_prime_fibs_up_to(89))


# ---- invalid input behavior ----

@pytest.mark.parametrize("bad", [0, -1, -2, -100])
def test_invalid_nonpositive_raises(bad):
    with pytest.raises(Exception):
        prime_fib(bad)


@given(st.integers(max_value=0))
def test_property_nonpositive_raises(n):
    with pytest.raises(Exception):
        prime_fib(n)


@pytest.mark.parametrize("bad", [2.5, 3.0, "3", None, [3], 2.0])
def test_invalid_type_raises(bad):
    with pytest.raises(Exception):
        prime_fib(bad)
